content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --bg-color: #f3f4f6;
  --card-bg: #ffffff;
  --text-main: #1f2937;
  --text-muted: #6b7280;
  --border-color: #e5e7eb;
  --danger-color: #ef4444;
  --danger-hover: #dc2626;
  --radius: 8px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.app-container {
  background-color: var(--card-bg);
  width: 100%;
  max-width: 500px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.header {
  text-align: center;
}

.title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-main);
}

.input-form {
  display: flex;
  gap: 8px;
}

.todo-input {
  flex: 1;
  padding: 10px 14px;
  font-size: 1rem;
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.todo-input:focus {
  border-color: var(--primary-color);
}

.todo-input:focus-visible {
  outline: none;
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.2);
}

.btn {
  padding: 10px 16px;
  font-size: 1rem;
  font-weight: 500;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background-color 0.2s;
}

.btn:focus-visible,
.todo-checkbox:focus-visible,
.todo-delete:focus-visible {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
}

.btn-primary {
  background-color: var(--primary-color);
  color: #ffffff;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.todo-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-height: 400px;
  overflow-y: auto;
}

.todo-list::-webkit-scrollbar {
  width: 6px;
}

.todo-list::-webkit-scrollbar-track {
  background: transparent;
}

.todo-list::-webkit-scrollbar-thumb {
  background: var(--border-color);
  border-radius: 3px;
}

.todo-list::-webkit-scrollbar-thumb:hover {
  background: var(--text-muted);
}

.todo-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 14px;
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  gap: 12px;
  transition: background-color 0.2s;
}

.todo-item:hover {
  background-color: #f9fafb;
}

.todo-checkbox {
  width: 18px;
  height: 18px;
  cursor: pointer;
}

.todo-text {
  flex: 1;
  font-size: 1rem;
  word-break: break-all;
}

.todo-item.completed .todo-text {
  text-decoration: line-through;
  color: var(--text-muted);
}

.todo-delete {
  background-color: transparent;
  color: var(--danger-color);
  padding: 6px 10px;
  font-size: 0.875rem;
}

.todo-delete:hover {
  background-color: #fee2e2;
  color: var(--danger-hover);
}

.empty-message {
  text-align: center;
  color: var(--text-muted);
  padding: 20px 0;
  font-size: 0.95rem;
}

export interface TodoItem {
  id: string;
  text: string;
  completed: boolean;
  createdAt?: number;
  priority?: 'low' | 'medium' | 'high';
}

import { FC, useState, KeyboardEvent, ChangeEvent } from 'react';
import { TodoItem as TodoItemType } from '../types';

interface TodoItemProps {
  item: TodoItemType;
  onToggle: (id: string) => void;
  onDelete: (id: string) => void;
  onEdit?: (id: string, text: string) => void;
}

export const TodoItem: FC<TodoItemProps> = ({ item, onToggle, onDelete, onEdit }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editText, setEditText] = useState(item.text);

  const handleDoubleClick = () => {
    setIsEditing(true);
    setEditText(item.text);
  };

  const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
    setEditText(e.target.value);
  };

  const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      if (editText.trim()) {
        onEdit?.(item.id, editText.trim());
      }
      setIsEditing(false);
    } else if (e.key === 'Escape') {
      setEditText(item.text);
      setIsEditing(false);
    }
  };

  const handleBlur = () => {
    if (editText.trim()) {
      onEdit?.(item.id, editText.trim());
    } else {
      setEditText(item.text);
    }
    setIsEditing(false);
  };

  return (
    <li className={`todo-item ${item.completed ? 'completed' : ''}`}>
      <input
        type="checkbox"
        className="todo-checkbox"
        checked={item.completed}
        onChange={() => onToggle(item.id)}
      />
      {isEditing ? (
        <input
          type="text"
          className="todo-input"
          value={editText}
          onChange={handleChange}
          onKeyDown={handleKeyDown}
          onBlur={handleBlur}
          autoFocus
        />
      ) : (
        <span className="todo-text" onDoubleClick={handleDoubleClick}>
          {item.text}
        </span>
      )}
      <button
        type="button"
        className="btn todo-delete"
        onClick={() => onDelete(item.id)}
      >
        削除
      </button>
    </li>
  );
};

export default TodoItem;

import { FC } from 'react';
import { TodoItem as TodoItemType } from '../types';
import { TodoItem } from './TodoItem';

interface TodoListProps {
  items?: TodoItemType[];
  onToggle: (id: string) => void;
  onDelete: (id: string) => void;
  filter?: 'all' | 'active' | 'completed';
}

export const TodoList: FC<TodoListProps> = ({ items = [], onToggle, onDelete, filter = 'all' }) => {
  if (items.length === 0) {
    let message = 'やることリストはありません';
    if (filter === 'active') {
      message = '未完了のタスクはありません';
    } else if (filter === 'completed') {
      message = '完了済みのタスクはありません';
    }
    return <div className="empty-message">{message}</div>;
  }

  return (
    <ul className="todo-list">
      {items.map((item) => (
        <TodoItem
          key={item.id}
          item={item}
          onToggle={onToggle}
          onDelete={onDelete}
        />
      ))}
    </ul>
  );
};

export default TodoList;

import { useState, FC, FormEvent, useEffect } from 'react';
import { TodoItem } from './types';
import { TodoList } from './components/TodoList';
import './index.css';

export const App: FC = () => {
  const [todos, setTodos] = useState<TodoItem[]>(() => {
    const saved = localStorage.getItem('todos');
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch (e) {
        console.error(e);
      }
    }
    return [
      { id: '1', text: 'Reactのプロジェクトを作成する', completed: true },
      { id: '2', text: 'TodoリストのUIを実装する', completed: false },
      { id: '3', text: 'コンポーネントを分割して綺麗に整理する', completed: false },
    ];
  });
  const [inputText, setInputText] = useState('');
  const [filter, setFilter] = useState<'all' | 'active' | 'completed'>('all');

  useEffect(() => {
    localStorage.setItem('todos', JSON.stringify(todos));
  }, [todos]);

  const handleAddTodo = (e: FormEvent) => {
    e.preventDefault();
    if (!inputText.trim()) return;

    const newTodo: TodoItem = {
      id: Date.now().toString(),
      text: inputText.trim(),
      completed: false,
    };

    setTodos([newTodo, ...todos]);
    setInputText('');
  };

  const handleToggleTodo = (id: string) => {
    setTodos(
      todos.map((todo) =>
        todo.id === id ? { ...todo, completed: !todo.completed } : todo
      )
    );
  };

  const handleDeleteTodo = (id: string) => {
    setTodos(todos.filter((todo) => todo.id !== id));
  };

  const handleClearCompleted = () => {
    setTodos(todos.filter((todo) => !todo.completed));
  };

  const filteredTodos = todos.filter((todo) => {
    if (filter === 'active') return !todo.completed;
    if (filter === 'completed') return todo.completed;
    return true;
  });

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">やることリスト</h1>
      </header>
      <form className="input-form" onSubmit={handleAddTodo}>
        <input
          type="text"
          className="todo-input"
          placeholder="新しいやること..."
          value={inputText}
          onChange={(e) => setInputText(e.target.value)}
        />
        <button type="submit" className="btn btn-primary">
          追加
        </button>
      </form>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '8px' }}>
        <div style={{ display: 'flex', gap: '4px' }}>
          <button
            type="button"
            className={`btn ${filter === 'all' ? 'btn-primary' : ''}`}
            onClick={() => setFilter('all')}
          >
            すべて
          </button>
          <button
            type="button"
            className={`btn ${filter === 'active' ? 'btn-primary' : ''}`}
            onClick={() => setFilter('active')}
          >
            未完了
          </button>
          <button
            type="button"
            className={`btn ${filter === 'completed' ? 'btn-primary' : ''}`}
            onClick={() => setFilter('completed')}
          >
            完了済み
          </button>
        </div>
        <button
          type="button"
          className="btn todo-delete"
          onClick={handleClearCompleted}
        >
          完了済みを削除
        </button>
      </div>
      <TodoList
        items={filteredTodos}
        onToggle={handleToggleTodo}
        onDelete={handleDeleteTodo}
        filter={filter}
      />
    </div>
  );
};

export default App;
